Date: Mon, 15 Apr 2024 13:35:10 +0200
Subject: [PATCH] fixed bug introduced in 48e63767


diff --git a/src/utils/error.c b/src/utils/error.c
index 08206eec6..59e8a5055 100644
--- a/src/utils/error.c
+++ b/src/utils/error.c
@@ -2254,12 +2254,18 @@ Bool gf_parse_frac(const char *value, GF_Fraction *frac)
 	return res;
 }

-Bool gf_strict_atoi(const char* str, int* ans) {
+Bool gf_strict_atoi(const char* str, s32* ans) {
     char* end_ptr = NULL;
     *ans = strtol(str, &end_ptr, 10);
     return !isspace(*str) && end_ptr != str && *end_ptr == '\0';
 }

+Bool gf_strict_atoui(const char* str, u32* ans) {
+	char* end_ptr = NULL;
+	*ans = strtoul(str, &end_ptr, 10);
+	return !isspace(*str) && end_ptr != str && *end_ptr == '\0';
+}
+
 const char* gf_strmemstr(const char *data, u32 data_size, const char *pat)
 {
        if (!pat || !data) return NULL;
